INSERT INTO stock_log (
    product_id, warehouse_id, change_type, change_quantity,
    before_quantity, after_quantity, order_no, operator_id
) VALUES (
             #{log.productId}, #{log.warehouseId}, #{log.changeType},
             #{log.changeQuantity}, #{log.beforeQuantity}, #{log.afterQuantity},
             #{log.orderNo}, #{log.operatorId}
         )

mapper.select:
SELECT sl.id, p.name AS product_name, p.code AS product_code, w.name AS warehouse_name, sl.change_type, sl.change_quantity, sl.before_quantity, sl.after_quantity, sl.order_no, u.real_name AS operator_name, sl.create_time FROM stock_log sl INNER JOIN product p ON sl.product_id = p.id INNER JOIN warehouse w ON sl.warehouse_id = w.id LEFT JOIN sys_user u ON sl.operator_id = u.id
AND sl.product_id = #{dto.productId}
AND sl.warehouse_id = #{dto.warehouseId}
AND sl.change_type = #{dto.changeType}
AND sl.create_time >= #{dto.startDate}
AND sl.create_time <= CAST(CONCAT(#{dto.endDate}, ' 23:59:59') AS DATETIME)
ORDER BY sl.create_time DESC, sl.id DESC -- 最新变动在前 LIMIT #{offset}, #{dto.pageSize}

SELECT COUNT(*)
FROM stock_log sl


        AND sl.product_id = #{dto.productId}


        AND sl.warehouse_id = #{dto.warehouseId}


        AND sl.change_type = #{dto.changeType}


        AND sl.create_time >= #{dto.startDate}


        AND sl.create_time <= CAST(CONCAT(#{dto.endDate}, ' 23:59:59') AS DATETIME)
